"""Go · referencia completa (etapas 6 y 7)."""
from .tabla import filas

E6 = filas(r"""
Paquete strings ¦ strings ¦ paquete con funciones para trabajar con textos ¦ limpiar y buscar en lo que escribe el usuario ¦ package main⏎import ("fmt"; "strings")⏎func main() { s := "  Hola Go  "; fmt.Println(strings.ToUpper(strings.TrimSpace(s)), strings.Contains(s, "Go")) } ¦ limpia, pasa a mayúsculas y busca ¦ olvidar que los textos no cambian y hay que guardar el resultado
strings.Split y Join ¦ strings.Split ¦ funciones para separar y unir textos ¦ procesar una línea CSV ¦ package main⏎import ("fmt"; "strings")⏎func main() { p := strings.Split("ana,luis", ","); fmt.Println(strings.Join(p, " | ")) } ¦ separa y une con barras ¦ concatenar en un bucle con + en textos largos
strings.Builder ¦ strings.Builder ¦ tipo para armar textos largos de forma eficiente ¦ construir un reporte línea por línea ¦ package main⏎import ("fmt"; "strings")⏎func main() { var b strings.Builder; for i := 1; i <= 3; i++ { fmt.Fprintf(&b, "línea %d\n", i) }; fmt.Print(b.String()) } ¦ arma tres líneas de texto ¦ usar + en bucles grandes
Paquete strconv ¦ strconv.Atoi ¦ paquete para convertir entre texto y números ¦ leer un número escrito por el usuario ¦ package main⏎import ("fmt"; "strconv")⏎func main() { n, err := strconv.Atoi("42"); fmt.Println(n+1, err, strconv.Itoa(7)+"!") } ¦ convierte texto a número y al revés ¦ ignorar el error que devuelve Atoi
Paquete time ¦ time ¦ paquete para fechas, horas y duraciones ¦ medir cuánto tarda una tarea ¦ package main⏎import ("fmt"; "time")⏎func main() { d := 90 * time.Minute; fmt.Println(d, time.Date(2026, 12, 24, 0, 0, 0, 0, time.UTC).Weekday()) } ¦ muestra una duración y el día de la semana ¦ usar números sueltos en vez de time.Duration
Formato de fechas en Go ¦ Format ¦ formato de fechas usando la fecha de referencia 2006-01-02 ¦ mostrar una fecha como 24/12/2026 ¦ package main⏎import ("fmt"; "time")⏎func main() { d := time.Date(2026, 12, 24, 0, 0, 0, 0, time.UTC); fmt.Println(d.Format("02/01/2006")) } ¦ muestra la fecha con barras ¦ usar letras como dd/mm/yyyy, que Go no entiende
Paquete os ¦ os ¦ paquete para hablar con el sistema operativo ¦ leer variables de entorno y argumentos ¦ package main⏎import ("fmt"; "os")⏎func main() { fmt.Println(len(os.Args) > 0, os.Getenv("NO_EXISTE") == "") } ¦ revisa los argumentos y una variable ¦ olvidar que os.Args[0] es el programa
Leer y escribir archivos ¦ os.WriteFile ¦ funciones para guardar y leer archivos ¦ guardar notas en un archivo ¦ package main⏎import ("fmt"; "os"; "path/filepath")⏎func main() { f := filepath.Join(os.TempDir(), "n.txt"); os.WriteFile(f, []byte("hola"), 0644); b, _ := os.ReadFile(f); fmt.Println(string(b)) } ¦ escribe y lee un archivo ¦ ignorar los errores de lectura
bufio.Scanner ¦ bufio.Scanner ¦ tipo para leer texto línea por línea ¦ procesar un archivo grande o la entrada del teclado ¦ package main⏎import ("bufio"; "fmt"; "strings")⏎func main() { s := bufio.NewScanner(strings.NewReader("uno\ndos")); for s.Scan() { fmt.Println("-", s.Text()) } } ¦ recorre el texto línea por línea ¦ leer todo con ReadAll en archivos enormes
Paquete sort y slices ¦ slices.Sort ¦ funciones para ordenar y buscar en slices ¦ ordenar una lista de números ¦ package main⏎import ("fmt"; "slices")⏎func main() { n := []int{3, 1, 2}; slices.Sort(n); fmt.Println(n, slices.Contains(n, 2), slices.Index(n, 3)) } ¦ ordena y busca en el slice ¦ escribir el ordenamiento a mano
Paquete maps ¦ maps.Keys ¦ funciones para trabajar con mapas ¦ obtener las claves de un mapa ordenadas ¦ package main⏎import ("fmt"; "maps"; "slices")⏎func main() { m := map[string]int{"b": 2, "a": 1}; fmt.Println(slices.Sorted(maps.Keys(m))) } ¦ muestra las claves en orden ¦ esperar que los mapas se recorran en orden
Range sobre enteros y funciones ¦ range 5 ¦ recorrer números o iteradores con range ¦ repetir algo cinco veces ¦ package main⏎import "fmt"⏎func main() { for i := range 3 { fmt.Print(i, " ") } } ¦ muestra 0 1 2 ¦ usar una versión vieja de Go sin esta función
Etiquetas de structs ¦ `json:"nombre"` ¦ información extra en los campos de un struct ¦ decidir cómo se llaman los campos en JSON ¦ package main⏎import ("encoding/json"; "fmt")⏎type U struct { Nombre string `json:"nombre"`; Clave string `json:"-"` }⏎func main() { b, _ := json.Marshal(U{"Ana", "123"}); fmt.Println(string(b)) } ¦ convierte a JSON sin la clave ¦ dejar campos en minúscula y que no se exporten
Leer JSON ¦ json.Unmarshal ¦ función que convierte JSON en structs ¦ leer la respuesta de una API ¦ package main⏎import ("encoding/json"; "fmt")⏎type U struct{ Name string }⏎func main() { var u U; json.Unmarshal([]byte(`{"name":"Ana"}`), &u); fmt.Println(u.Name) } ¦ lee el nombre del JSON ¦ olvidar pasar el puntero &u
Errores con errors.As ¦ errors.As ¦ función que busca un tipo de error dentro de otro ¦ saber si un error es de validación ¦ package main⏎import ("errors"; "fmt")⏎type ErrVal struct{ Campo string }⏎func (e ErrVal) Error() string { return "campo " + e.Campo }⏎func main() { err := fmt.Errorf("guardar: %w", ErrVal{"edad"}); var v ErrVal; fmt.Println(errors.As(err, &v), v.Campo) } ¦ encuentra el error de validación envuelto ¦ comparar errores con == cuando están envueltos
""")

E7 = filas(r"""
context ¦ context ¦ paquete para cancelar operaciones y poner tiempos límite ¦ detener una petición que tarda demasiado ¦ package main⏎import ("context"; "fmt"; "time")⏎func main() { ctx, cancel := context.WithTimeout(context.Background(), 50*time.Millisecond); defer cancel(); select { case <-time.After(time.Second): fmt.Println("listo"); case <-ctx.Done(): fmt.Println(ctx.Err()) } } ¦ cancela la espera por tiempo ¦ olvidar llamar cancel
select con canales ¦ select ¦ sentencia que espera el primero de varios canales ¦ atender mensajes o un tiempo límite ¦ package main⏎import ("fmt"; "time")⏎func main() { c := make(chan string); go func() { c <- "mensaje" }(); select { case m := <-c: fmt.Println(m); case <-time.After(time.Second): fmt.Println("tiempo") } } ¦ recibe el mensaje antes del tiempo límite ¦ usar select vacío y bloquear para siempre
Worker pool ¦ worker pool ¦ grupo fijo de goroutines que procesan tareas ¦ procesar muchas imágenes sin saturar el equipo ¦ package main⏎import ("fmt"; "sync")⏎func main() { t := make(chan int, 5); var wg sync.WaitGroup; var mu sync.Mutex; s := 0⏎for w := 0; w < 3; w++ { wg.Add(1); go func() { defer wg.Done(); for x := range t { mu.Lock(); s += x; mu.Unlock() } }() }⏎for i := 1; i <= 5; i++ { t <- i }; close(t); wg.Wait(); fmt.Println(s) } ¦ suma con tres trabajadores ¦ olvidar cerrar el canal y que los trabajadores esperen siempre
errgroup ¦ errgroup ¦ grupo de goroutines que devuelve el primer error ¦ cargar varios datos y cancelar si uno falla ¦ // g, ctx := errgroup.WithContext(ctx)⏎// g.Go(func() error { return cargarUsuarios(ctx) })⏎// if err := g.Wait(); err != nil { ... }⏎package main⏎func main() { println("errgroup") } ¦ espera todas las tareas y devuelve el error ¦ ignorar el contexto cancelado
sync.RWMutex ¦ RWMutex ¦ candado que permite muchos lectores o un escritor ¦ proteger una caché muy leída ¦ package main⏎import ("fmt"; "sync")⏎func main() { var mu sync.RWMutex; m := map[string]int{"a": 1}; mu.RLock(); fmt.Println(m["a"]); mu.RUnlock() } ¦ lee el mapa con un candado de lectura ¦ escribir con RLock
Detector de carreras ¦ -race ¦ herramienta que encuentra accesos peligrosos entre goroutines ¦ descubrir errores de concurrencia ¦ // go run -race main.go⏎// go test -race ./...⏎package main⏎func main() { println("race") } ¦ ejecuta el programa buscando carreras ¦ creer que si funciona una vez no hay carreras
net/http servidor ¦ http.HandleFunc ¦ paquete para crear servidores web ¦ hacer una API sin frameworks ¦ // http.HandleFunc("GET /hola/{nombre}", func(w http.ResponseWriter, r *http.Request) { fmt.Fprintf(w, "Hola %s", r.PathValue("nombre")) })⏎// http.ListenAndServe(":8080", nil)⏎package main⏎func main() { println("servidor") } ¦ responde con el nombre de la ruta ¦ olvidar manejar el error de ListenAndServe
Responder JSON en Go ¦ json.NewEncoder ¦ forma de enviar JSON en una respuesta HTTP ¦ devolver datos desde tu API ¦ // w.Header().Set("Content-Type", "application/json")⏎// json.NewEncoder(w).Encode(map[string]any{"ok": true})⏎package main⏎func main() { println(`{"ok":true}`) } ¦ responde con JSON ¦ olvidar la cabecera Content-Type
Middleware en Go ¦ http.Handler ¦ funciones que envuelven handlers para añadir comportamiento ¦ registrar cada petición ¦ // func log(next http.Handler) http.Handler { return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { fmt.Println(r.URL.Path); next.ServeHTTP(w, r) }) }⏎package main⏎func main() { println("middleware") } ¦ imprime la ruta de cada petición ¦ olvidar llamar next.ServeHTTP
Cliente HTTP ¦ http.Get ¦ funciones para pedir datos a otras APIs ¦ consumir una API externa ¦ // c := &http.Client{Timeout: 10 * time.Second}⏎// r, err := c.Get("https://api.github.com"); defer r.Body.Close()⏎package main⏎func main() { println("cliente") } ¦ pide datos con tiempo límite ¦ olvidar cerrar el Body
database/sql ¦ sql.Open ¦ paquete para conectarse a bases de datos ¦ consultar MySQL o PostgreSQL ¦ // db, _ := sql.Open("mysql", "root:@/tienda")⏎// row := db.QueryRow("SELECT nombre FROM producto WHERE id = ?", 7)⏎package main⏎func main() { println("sql") } ¦ consulta un producto con parámetros ¦ concatenar valores dentro del SQL
Módulos de Go ¦ go mod init ¦ sistema de dependencias de Go ¦ crear un proyecto e instalar librerías ¦ // go mod init github.com/ana/app⏎// go get github.com/gin-gonic/gin⏎// go mod tidy⏎package main⏎func main() { println("módulos") } ¦ crea el módulo e instala una librería ¦ editar go.sum a mano
Pruebas de tabla ¦ t.Run ¦ forma de probar muchos casos con un solo test ¦ probar una función con varios valores ¦ // func TestDoble(t *testing.T) { casos := []struct{ in, out int }{{1, 2}, {3, 6}}⏎//   for _, c := range casos { if doble(c.in) != c.out { t.Errorf("doble(%d)", c.in) } } }⏎package main⏎func main() { println("tabla") } ¦ prueba varios casos en un bucle ¦ copiar el mismo test muchas veces
Benchmarks ¦ testing.B ¦ pruebas que miden la velocidad del código ¦ comparar dos formas de hacer algo ¦ // func BenchmarkSuma(b *testing.B) { for b.Loop() { suma(1000) } }⏎// go test -bench=.⏎package main⏎func main() { println("bench") } ¦ mide cuánto tarda la función ¦ optimizar sin medir
go vet y golangci-lint ¦ go vet ¦ herramientas que encuentran errores comunes ¦ revisar el código antes de publicar ¦ // go vet ./...⏎// golangci-lint run⏎package main⏎func main() { println("vet") } ¦ revisa el proyecto ¦ ignorar las advertencias
Compilar para otros sistemas ¦ GOOS ¦ variables que eligen el sistema y procesador de destino ¦ crear un ejecutable para Windows desde Linux ¦ // GOOS=windows GOARCH=amd64 go build -o app.exe⏎package main⏎func main() { println("cruzada") } ¦ compila un .exe para Windows ¦ olvidar que cgo complica la compilación cruzada
embed ¦ //go:embed ¦ forma de meter archivos dentro del ejecutable ¦ distribuir una web con un solo archivo ¦ // //go:embed static/*⏎// var archivos embed.FS⏎package main⏎func main() { println("embed") } ¦ incluye la carpeta static en el binario ¦ poner el comentario lejos de la variable
Gin y frameworks web ¦ gin ¦ frameworks populares para APIs en Go ¦ crear rutas con menos código ¦ // r := gin.Default()⏎// r.GET("/ping", func(c *gin.Context) { c.JSON(200, gin.H{"ok": true}) })⏎// r.Run()⏎package main⏎func main() { println("gin") } ¦ crea una ruta que responde JSON ¦ usar un framework cuando net/http ya basta
Proyecto final con Go ¦ go build ¦ programa completo con structs, errores, archivos y pruebas ¦ practicar todo lo aprendido ¦ package main⏎import "fmt"⏎type Tarea struct { Texto string; Hecha bool }⏎func main() { t := []Tarea{{"Estudiar Go", false}}; for _, x := range t { fmt.Println("•", x.Texto) } } ¦ muestra una lista de tareas ¦ ignorar los errores con _ en todas partes
""")

